// ===== OPEN MODAL =====
function openModal(type) {
  const d = modalData[type];
  if (!d) return;

  // Try to load image, fall back to placeholder icon
  const imgHTML = d.img
    ? `<img src="${d.img}" class="modal-img" alt="${d.title}"
        onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';">
       <div class="modal-img-placeholder" style="display:none;">${d.icon}</div>`
    : `<div class="modal-img-placeholder">${d.icon}</div>`;

  const linkHTML = d.link
    ? `<a href="${d.link}" target="_blank" class="modal-action">Visit Live Site →</a>`
    : '';

  document.getElementById('modal-body').innerHTML = `
    ${imgHTML}
    <div class="modal-body">
      <div class="modal-tag">${d.tag}</div>
      <div class="modal-title">${d.title}</div>
      <div class="modal-desc">${d.desc}</div>
      ${linkHTML}
    </div>
  `;

  document.getElementById('modal').classList.add('active');
  document.body.style.overflow = 'hidden';
}

// ===== CLOSE MODAL =====
function closeModal() {
  document.getElementById('modal').classList.remove('active');
  document.body.style.overflow = '';
}

// Close on overlay click
function handleOverlayClick(e) {
  if (e.target === document.getElementById('modal')) closeModal();
}

// Close on Escape key
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') closeModal();
});


